const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

// Prices are floats, so compare totals with a tolerance instead of strict equality.
function assertClose(actual, expected, epsilon = 1e-9) {
  assert.ok(
    Math.abs(actual - expected) < epsilon,
    `expected ${actual} to be within ${epsilon} of ${expected}`
  );
}

function itemNames(cart) {
  return cart.items.map(i => i.name);
}

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('constructor', () => {
    it('starts empty with no discount', () => {
      assert.deepEqual(cart.items, []);
      assert.equal(cart.discount, 0);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('addItem', () => {
    it('adds a new item with its name, price and quantity', () => {
      cart.addItem('apple', 1.5, 2);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
    });

    it('adds distinct items as separate line items', () => {
      cart.addItem('apple', 1.5, 2);
      cart.addItem('banana', 0.25, 6);
      assert.deepEqual(itemNames(cart), ['apple', 'banana']);
      assert.equal(cart.getItemCount(), 2);
    });

    it('merges quantity when the same item is added again', () => {
      cart.addItem('apple', 1.5, 2);
      cart.addItem('apple', 1.5, 3);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('allows a price of zero (free item)', () => {
      cart.addItem('sticker', 0, 1);
      assert.deepEqual(cart.items, [{ name: 'sticker', price: 0, quantity: 1 }]);
    });

    it('rejects a negative price', () => {
      assert.throws(() => cart.addItem('apple', -1, 1), RangeError);
    });

    it('rejects a negative quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, -1), RangeError);
    });

    it('rejects a zero quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 0), RangeError);
    });

    it('rejects a fractional quantity', () => {
      assert.throws(() => cart.addItem('apple', 1, 1.5), RangeError);
    });

    for (const price of [NaN, Infinity, -Infinity, '5', null, undefined]) {
      it(`rejects a non-numeric or non-finite price (${String(price)})`, () => {
        assert.throws(() => cart.addItem('apple', price, 1), RangeError);
      });
    }

    for (const quantity of [NaN, Infinity, '2', null, undefined]) {
      it(`rejects a non-numeric or non-finite quantity (${String(quantity)})`, () => {
        assert.throws(() => cart.addItem('apple', 1, quantity), RangeError);
      });
    }

    it('leaves the cart unchanged when an add is rejected', () => {
      cart.addItem('apple', 1.5, 2);
      assert.throws(() => cart.addItem('banana', -1, 1));
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
    });

    it('rejects an invalid quantity when merging into an existing item', () => {
      cart.addItem('apple', 1.5, 2);
      assert.throws(() => cart.addItem('apple', 1.5, -5), RangeError);
      assert.equal(cart.items[0].quantity, 2);
    });
  });

  describe('removeItem', () => {
    beforeEach(() => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);
      cart.addItem('cherry', 3, 1);
    });

    it('removes only the named item', () => {
      cart.removeItem('banana');
      assert.deepEqual(itemNames(cart), ['apple', 'cherry']);
    });

    it('does not modify the remaining items', () => {
      cart.removeItem('banana');
      assert.deepEqual(cart.items, [
        { name: 'apple', price: 1, quantity: 1 },
        { name: 'cherry', price: 3, quantity: 1 },
      ]);
    });

    it('removes the whole line item regardless of quantity', () => {
      cart.addItem('apple', 1, 4);
      cart.removeItem('apple');
      assert.deepEqual(itemNames(cart), ['banana', 'cherry']);
    });

    it('can empty the cart', () => {
      cart.removeItem('apple');
      cart.removeItem('banana');
      cart.removeItem('cherry');
      assert.equal(cart.getItemCount(), 0);
    });

    it('allows an item to be re-added after removal', () => {
      cart.removeItem('apple');
      cart.addItem('apple', 1, 2);
      assert.deepEqual(itemNames(cart), ['banana', 'cherry', 'apple']);
      assert.equal(cart.items[2].quantity, 2);
    });

    it('throws when the item is not in the cart and leaves the cart unchanged', () => {
      const before = structuredClone(cart.items);
      assert.throws(() => cart.removeItem('durian'), /not found/);
      assert.deepEqual(cart.items, before);
    });

    it('throws when removing the same item twice', () => {
      cart.removeItem('apple');
      assert.throws(() => cart.removeItem('apple'), /not found/);
    });

    it('throws when removing from an empty cart', () => {
      const empty = new ShoppingCart();
      assert.throws(() => empty.removeItem('apple'), /not found/);
    });
  });

  describe('getTotal', () => {
    it('returns 0 for an empty cart', () => {
      assert.equal(cart.getTotal(), 0);
    });

    it('returns price * quantity for a single item', () => {
      cart.addItem('apple', 1.5, 4);
      assert.equal(cart.getTotal(), 6);
    });

    it('sums every item in the cart, including the last one', () => {
      cart.addItem('apple', 1, 2);
      cart.addItem('banana', 2, 3);
      cart.addItem('cherry', 10, 1);
      assert.equal(cart.getTotal(), 18);
    });

    it('handles fractional prices', () => {
      cart.addItem('widget', 19.99, 3);
      assertClose(cart.getTotal(), 59.97);
    });

    it('reflects merged quantities', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('apple', 2, 2);
      assert.equal(cart.getTotal(), 6);
    });

    it('reflects removed items', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('banana', 5, 1);
      cart.removeItem('banana');
      assert.equal(cart.getTotal(), 2);
    });

    it('includes free items without affecting the total', () => {
      cart.addItem('sticker', 0, 10);
      cart.addItem('apple', 3, 1);
      assert.equal(cart.getTotal(), 3);
    });

    it('subtracts a percentage discount from the total', () => {
      cart.addItem('apple', 50, 2);
      cart.applyDiscount(10);
      assert.equal(cart.getTotal(), 90);
    });

    it('returns the full total with a 0% discount', () => {
      cart.addItem('apple', 50, 2);
      cart.applyDiscount(0);
      assert.equal(cart.getTotal(), 100);
    });

    it('returns 0 with a 100% discount', () => {
      cart.addItem('apple', 50, 2);
      cart.applyDiscount(100);
      assert.equal(cart.getTotal(), 0);
    });

    it('applies fractional discounts', () => {
      cart.addItem('apple', 80, 1);
      cart.applyDiscount(12.5);
      assertClose(cart.getTotal(), 70);
    });

    it('applies the discount to items added after the discount', () => {
      cart.applyDiscount(25);
      cart.addItem('apple', 40, 1);
      assert.equal(cart.getTotal(), 30);
    });

    it('never returns more than the undiscounted total', () => {
      cart.addItem('apple', 10, 3);
      const undiscounted = cart.getTotal();
      for (const percent of [0, 1, 33, 50, 99.9, 100]) {
        cart.applyDiscount(percent);
        assert.ok(cart.getTotal() <= undiscounted, `${percent}% discount increased the total`);
        assert.ok(cart.getTotal() >= 0, `${percent}% discount produced a negative total`);
      }
    });
  });

  describe('applyDiscount', () => {
    it('stores a valid discount', () => {
      cart.applyDiscount(15);
      assert.equal(cart.discount, 15);
    });

    it('accepts the boundary values 0 and 100', () => {
      cart.applyDiscount(0);
      assert.equal(cart.discount, 0);
      cart.applyDiscount(100);
      assert.equal(cart.discount, 100);
    });

    it('replaces the previous discount rather than stacking', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);
      cart.applyDiscount(20);
      assert.equal(cart.getTotal(), 80);
    });

    it('rejects a discount above 100', () => {
      assert.throws(() => cart.applyDiscount(100.01), RangeError);
      assert.throws(() => cart.applyDiscount(150), RangeError);
    });

    it('rejects a negative discount', () => {
      assert.throws(() => cart.applyDiscount(-0.01), RangeError);
      assert.throws(() => cart.applyDiscount(-10), RangeError);
    });

    for (const percent of [NaN, Infinity, -Infinity, '10', null, undefined]) {
      it(`rejects a non-numeric or non-finite discount (${String(percent)})`, () => {
        assert.throws(() => cart.applyDiscount(percent), RangeError);
      });
    }

    it('keeps the previous discount when an invalid one is rejected', () => {
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(10);
      assert.throws(() => cart.applyDiscount(200));
      assert.equal(cart.discount, 10);
      assert.equal(cart.getTotal(), 90);
    });
  });

  describe('getItemCount', () => {
    it('counts distinct line items, not total quantity', () => {
      cart.addItem('apple', 1, 5);
      cart.addItem('banana', 1, 3);
      cart.addItem('apple', 1, 2);
      assert.equal(cart.getItemCount(), 2);
    });

    it('decreases when an item is removed', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 1, 1);
      cart.removeItem('apple');
      assert.equal(cart.getItemCount(), 1);
    });
  });

  // One targeted test per original bug. Each of these fails against the
  // original implementation and would fail again if that bug were reintroduced.
  describe('regressions', () => {
    it('Bug 1: addItem rejects negative price and quantity instead of corrupting the cart', () => {
      cart.addItem('apple', 1, 5);

      // Previously accepted: a negative quantity reduced the stored quantity
      // (here to -5) and a negative price made the total negative.
      assert.throws(() => cart.addItem('apple', 1, -10), RangeError);
      assert.throws(() => cart.addItem('refund', -100, 1), RangeError);

      assert.deepEqual(cart.items, [{ name: 'apple', price: 1, quantity: 5 }]);
      assert.equal(cart.getTotal(), 5);
    });

    it('Bug 2a: removeItem removes the matching item and leaves the others intact', () => {
      // Previously `i.name = name` renamed every item to "apple" and kept them all.
      // Writing `i.name === name` instead would keep only the item being removed.
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);

      cart.removeItem('apple');

      assert.deepEqual(cart.items, [{ name: 'banana', price: 2, quantity: 1 }]);
    });

    it('Bug 2b: removeItem reports a missing item instead of silently mutating the cart', () => {
      // Previously removing a missing item raised no error and renamed every item to "cherry".
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 1);

      assert.throws(() => cart.removeItem('cherry'), /not found/);

      assert.deepEqual(itemNames(cart), ['apple', 'banana']);
    });

    it('Bug 3: getTotal does not read past the end of the items array', () => {
      // Previously the loop used `<=`, so it read items[length], which is
      // undefined, and threw a TypeError on every cart, even an empty one.
      assert.doesNotThrow(() => cart.getTotal());
      assert.equal(cart.getTotal(), 0);

      cart.addItem('apple', 2, 3);
      cart.addItem('banana', 4, 1);
      assert.doesNotThrow(() => cart.getTotal());
      assert.equal(cart.getTotal(), 10);
    });

    it('Bug 4: getTotal subtracts the discount instead of adding it', () => {
      // Previously a 20% discount on 100 gave 120.
      cart.addItem('apple', 100, 1);
      cart.applyDiscount(20);
      assert.equal(cart.getTotal(), 80);
    });

    it('Bug 5: applyDiscount rejects out-of-range values', () => {
      // Previously any value was accepted: 150% gave a negative total and -10% a surcharge.
      cart.addItem('apple', 100, 1);

      assert.throws(() => cart.applyDiscount(150), RangeError);
      assert.throws(() => cart.applyDiscount(-10), RangeError);

      assert.equal(cart.discount, 0);
      assert.equal(cart.getTotal(), 100);
    });
  });
});

