// Runs the test suite against the original buggy file and against the fixed
// file with each bug reintroduced on its own, in a scratch copy of the repo.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

const root = process.argv[2];
const fixed = fs.readFileSync(path.join(root, 'src/cart.js'), 'utf8');
const buggy = fs.readFileSync('/tmp/cart.buggy.js', 'utf8');

const work = fs.mkdtempSync(path.join(os.tmpdir(), 'cart-mut-'));
fs.cpSync(path.join(root, 'tests'), path.join(work, 'tests'), { recursive: true });
fs.mkdirSync(path.join(work, 'src'));

const mutants = [
  ['ORIGINAL buggy file', () => buggy],
  ['FIXED file', s => s],
  ['Bug 1 only (no addItem checks)', s => s.replace(/    if \(!Number\.isFinite\(price\)[\s\S]*?positive integer`\);\n    }\n/, '')],
  ['Bug 2 only (filter uses =)', s => s.replace('i.name !== name', 'i.name = name')],
  ['Bug 2 alt (filter uses ===)', s => s.replace('i.name !== name', 'i.name === name')],
  ['Bug 2 only (no missing check)', s => s.replace(/    if \(!this\.items\.some[\s\S]*?\n    }\n/, '')],
  ['Bug 3 only (loop uses <=)', s => s.replace('i < this.items.length', 'i <= this.items.length')],
  ['Bug 4 only (discount added)', s => s.replace('return total - (', 'return total + (')],
  ['Bug 5 only (no discount checks)', s => s.replace(/    if \(!Number\.isFinite\(percent\)[\s\S]*?\n    }\n/, '')],
];

for (const [label, mutate] of mutants) {
  const src = mutate(fixed);
  if (label.startsWith('Bug') && src === fixed) {
    console.log(`${label.padEnd(34)} MUTATION DID NOT APPLY`);
    continue;
  }
  fs.writeFileSync(path.join(work, 'src/cart.js'), src);
  const r = spawnSync(process.execPath, ['--test', '--test-reporter=spec', 'tests/**/*.test.js'], {
    cwd: work, encoding: 'utf8', timeout: 30000,
